import math
print(math.floor(2.5), math.ceil(2.5), math.sqrt(16), math.gcd(12, 18), math.lcm(4, 6), math.factorial(20), math.comb(10, 3), math.perm(5, 2), math.isqrt(99), math.pow(2, 3))
print(math.exp(1), math.log(10), math.log2(8), math.log10(1000), math.log(8, 2), math.sin(1), math.cos(1), math.tan(1), math.asin(1), math.acos(0), math.atan(1), math.atan2(1, 1))
print(math.degrees(math.pi), math.radians(180), math.pi, math.e, math.inf, math.nan, math.isclose(1.0, 1.0 + 1e-10), math.isnan(math.nan), math.isinf(math.inf), math.fsum([0.1] * 10), math.hypot(3, 4))
